"""The security state of a profile, GENERATED by the engine from the files the core declares, and placed in every profile by copy.

A retail Firefox has, in `cert_storage`, the intermediates of the public web, OneCRL and the CRLite filters from its first second. The core downloads the three
inputs (`intermediates.json`, `onecrl.json`, `crlite.json` and the filter files that manifest names) and does NOT write cert_storage itself: the engine has a
GENERATE MODE, which imports the files through its own code, waits for the writes and exits. What it leaves is the directory cert_storage keeps, so its bytes are the
ones Firefox's own code wrote, never ours.

THE CONTRACT (fixed; the engine's side is written against the same text):
  * the core launches the CALLER'S LAUNCH LINE + `-profile <work profile>` (the line is an argv without the profile, e.g. `[<engine>, "-headless", "-no-remote"]`, or any other
    the caller names: the core knows no engine layout of its own and appends nothing but the profile; `default_argv` is the invisible launch) on an EMPTY work profile whose
    `user.js` holds EXACTLY four prefs: `SECURITY_STATE_GENERATE_PREF`
    = true and the absolute paths of the three inputs (`INTERMEDIATES_PREF`, `ONECRL_PREF`, `CRLITE_PREF`);
  * the engine writes NOTHING on stdout or stderr, and the core reads none of it (both go to the null device). The outcome is ONLY the exit code and the result file: exit 0 is ok;
    anything else is an error, and the result file then holds `"ok": false` and `"error": "<text>"` (an engine that exits non-zero and leaves no result file could not write
    its work profile: that is what the absence means);
  * the per-user directories of the engine point INSIDE the work directory (the one that holds the profile and is deleted at the end), so nothing is written outside it:
    `XDG_CONFIG_HOME`, `XDG_CACHE_HOME` (Linux) and `APPDATA`, `LOCALAPPDATA` (Windows) are set to subdirectories of it on every platform;
  * it leaves `<work profile>/security_state/` (`SECURITY_STATE_DIR_NAME`: at least `data.safe.bin` and `crlite.filter`, plus the `*.delta` files) and
    `<work profile>/securitystate-result.json` (`SECURITY_STATE_RESULT_NAME`):
      {"format":1,"ok":true,"error":null,"engine":{"version":"..","build_id":".."},
       "collections":{"intermediates":{"collection_timestamp":N},"onecrl":{"collection_timestamp":N},
                      "cert-revocations":{"collection_timestamp":N,"channel":"default"}},
       "crlite_filter_hashes":["<sha256 of the BYTES of each CRLite file it loaded, in lowercase hex: the full filter and the deltas>"]}

NOTHING THAT DOES NOT ADD UP IS KEPT. `validate_result` compares the report with what the core GAVE (the engine's build id, the three collection timestamps and the set of
CRLite hashes); a report that differs in one thing refuses the whole generation, and the directory is not copied. The core never trusts an exit code alone: an engine that
imported an older list, or loaded other filters than the ones declared, exits 0 as well.

NOTHING IS LEFT BEHIND, whatever happens: the work profile is deleted, and no process of the engine's tree is alive when `generate` returns or raises. The tree is the one the
core ends everywhere else: the engine is stamped with a session token (`process.SessionToken`) and what carries it is listed and ended by `process.reap_session` (the
sender of the shutdown pings that outlives the browser, a child of a hung engine). The result is copied into `out_dir` only when it is whole; the caller renames `out_dir` into its
cache in one step, so a reader sees a complete generation or none.

EVERY PROFILE GETS A COPY (`place_in_profile`), never a link, on Linux and on Windows: the engine rewrites the filter and delta files IN PLACE while it runs, and a link would
let one session write into the cache and into every other session's profile.

THE TEN-DAY RULE, in ONE place (`is_stale`). cert_storage keeps `last_crlite_update`, the time of the last write of a filter or a delta, and treats the filters as fresh only
while `now < last_crlite_update + 10 days` (security/manager/ssl/cert_storage/src/lib.rs:464-483, whole seconds). A generation of ours is made when WE run the engine, so one
made from old data would look fresh to cert_storage, which a retail Firefox never does, and cert_storage cannot be told another time. So the core never generates from stale data
(`_security_state`), and a launch with stale data copies `security_state/` WITHOUT the CRLite filter and its deltas (`place_in_profile(without_crlite=True)`): only
`data.safe.bin` (intermediates and OneCRL). FRESH is `now < updated_utc + CRLITE_MAX_AGE_S`; STALE is `now - updated_utc >= CRLITE_MAX_AGE_S`, so exactly ten days IS stale; a
date that cannot be read is stale.
"""
from __future__ import annotations

import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, FrozenSet, List, NamedTuple, Optional, Sequence

from . import _engine_env
from .constants import (
    CRLITE_CHANNEL,
    CRLITE_COLLECTION_ID,
    CRLITE_MAX_AGE_S,
    CRLITE_PREF,
    INTERMEDIATES_PREF,
    ONECRL_COLLECTION_ID,
    ONECRL_PREF,
    SECURITY_STATE_DIR_NAME,
    SECURITY_STATE_GENERATE_PREF,
    SECURITY_STATE_RESULT_NAME,
)
from .launch import _pref_literal
from .process import SessionToken, find_processes, reap_session, wait_until_gone
from .seal import EngineMismatch, read_engine_identity

__all__ = ["GENERATE_TIMEOUT_S", "GenerationError", "EngineId", "Expected", "Inputs", "engine_id_of", "default_argv", "generate", "validate_result", "place_in_profile", "age_warning", "is_stale"]

#: What the engine is given to import the files and exit, in seconds: an import of a few thousand records and a filter is a matter of seconds, and a hung engine is ended.
GENERATE_TIMEOUT_S = 120
#: The collection ids of the result (`INTERMEDIATES` is the Remote Settings collection `security-state/intermediates`, the report names it by its short id).
INTERMEDIATES_COLLECTION_ID = "intermediates"
#: The per-user directories of the engine, each a subdirectory of the work directory: variable -> name.
HOME_DIRECTORIES = (("XDG_CONFIG_HOME", "xdg-config"), ("XDG_CACHE_HOME", "xdg-cache"), ("APPDATA", "appdata"), ("LOCALAPPDATA", "localappdata"))
#: What the core waits for the tree to be gone after it has ended it, and for the work profile to be removable (Windows holds a directory a moment after its last process).
TREE_GONE_WAIT_S = 10.0
REMOVE_ATTEMPTS = 40
#: The files the engine must have left in `security_state/`.
CRLITE_FILTER_FILE_NAME = "crlite.filter"
REQUIRED_FILES = ("data.safe.bin", CRLITE_FILTER_FILE_NAME)

_HEX64 = re.compile(r"[0-9a-f]{64}")


class GenerationError(RuntimeError):
    """The engine did not generate the security state, or what it generated is not what the core gave it. Nothing was kept."""


@dataclass(frozen=True)
class EngineId:
    """What the engine says about itself (`application.ini`), the part a generation is tied to: a cert_storage written by one build is not handed to another."""

    version: Optional[str]
    build_id: str


def engine_id_of(binary: "str | os.PathLike[str]") -> EngineId:
    """The version and the build id of the engine at `binary`. A binary with no build id cannot be tied to a generation: `GenerationError`."""
    try:
        ident = read_engine_identity(binary)
    except EngineMismatch as e:
        raise GenerationError("cannot read the engine's identity: %s" % (e,)) from e
    if not ident.build_id:
        raise GenerationError("the engine at %s says no BuildID (application.ini: %s)" % (binary, "; ".join(ident.notes) or "no note"))
    return EngineId(version=ident.version, build_id=ident.build_id)


class Expected(NamedTuple):
    """What the report of the engine must say, from the inputs alone."""

    #: collection id (`intermediates`, `onecrl`, `cert-revocations`) -> collection_timestamp
    timestamps: Dict[str, int]
    #: sha256 (lowercase hex) of every CRLite file the manifest names: the full filter and the deltas
    crlite_hashes: FrozenSet[str]


def _load(path: Path, what: str) -> dict:
    try:
        data = json.loads(Path(path).read_bytes().decode("utf-8"))
    except (OSError, ValueError) as e:
        raise GenerationError("cannot read the %s file %s: %s" % (what, path, e)) from e
    if not isinstance(data, dict):
        raise GenerationError("the %s file %s is not a JSON object" % (what, path))
    return data


def _timestamp(data: dict, what: str) -> int:
    value = data.get("collection_timestamp")
    if isinstance(value, bool) or not isinstance(value, int):
        raise GenerationError("the %s file has no integer collection_timestamp (%r)" % (what, value))
    return value


@dataclass(frozen=True)
class Inputs:
    """The three files the engine imports (absolute paths of files that exist)."""

    intermediates: Path
    onecrl: Path
    crlite: Path

    def expected(self) -> Expected:
        """The collection timestamps and the CRLite hashes the files declare. A file that cannot be read or says none is `GenerationError`."""
        inter = _load(self.intermediates, "intermediates")
        crl = _load(self.onecrl, "onecrl")
        cr = _load(self.crlite, "crlite")
        hashes: List[str] = []
        parts = [cr.get("full")] + list(cr.get("deltas") or [])
        for part in parts:
            digest = part.get("sha256") if isinstance(part, dict) else None
            if not isinstance(digest, str) or not _HEX64.fullmatch(digest.lower()):
                raise GenerationError("the crlite manifest names a file with no sha256: %r" % (part,))
            hashes.append(digest.lower())
        return Expected(
            timestamps={
                INTERMEDIATES_COLLECTION_ID: _timestamp(inter, "intermediates"),
                ONECRL_COLLECTION_ID: _timestamp(crl, "onecrl"),
                CRLITE_COLLECTION_ID: _timestamp(cr, "crlite"),
            },
            crlite_hashes=frozenset(hashes),
        )


def validate_result(result: Any, inputs: Inputs, engine: EngineId) -> None:
    """Refuses a report that is not exactly what the core gave the engine. The message names what differs."""
    if not isinstance(result, dict):
        raise GenerationError("the result is not a JSON object")
    problems: List[str] = []
    if result.get("format") != 1 or isinstance(result.get("format"), bool):
        problems.append("format is %r, not 1" % (result.get("format"),))
    if result.get("ok") is not True:
        problems.append("ok is %r (error: %r)" % (result.get("ok"), result.get("error")))
    reported = result.get("engine")
    reported = reported if isinstance(reported, dict) else {}
    if reported.get("build_id") != engine.build_id:
        problems.append("engine build_id is %r, the core launched %r" % (reported.get("build_id"), engine.build_id))
    if engine.version is not None and reported.get("version") is not None and reported.get("version") != engine.version:
        problems.append("engine version is %r, the core launched %r" % (reported.get("version"), engine.version))
    expected = inputs.expected()
    collections = result.get("collections")
    collections = collections if isinstance(collections, dict) else {}
    for name, stamp in expected.timestamps.items():
        entry = collections.get(name)
        got = entry.get("collection_timestamp") if isinstance(entry, dict) else None
        if isinstance(got, bool) or got != stamp:
            problems.append("collection %s: collection_timestamp is %r, the file says %r" % (name, got, stamp))
    crl = collections.get(CRLITE_COLLECTION_ID)
    channel = crl.get("channel") if isinstance(crl, dict) else None
    if channel != CRLITE_CHANNEL:
        problems.append("collection %s: channel is %r, not %r" % (CRLITE_COLLECTION_ID, channel, CRLITE_CHANNEL))
    hashes = result.get("crlite_filter_hashes")
    if not isinstance(hashes, list) or not all(isinstance(h, str) and _HEX64.fullmatch(h) for h in hashes):
        problems.append("crlite_filter_hashes is not a list of lowercase sha256 hex strings (%r)" % (hashes,))
    else:
        got_set = set(hashes)
        if got_set != set(expected.crlite_hashes):
            missing = sorted(set(expected.crlite_hashes) - got_set)
            extra = sorted(got_set - set(expected.crlite_hashes))
            problems.append("crlite_filter_hashes differ from the manifest's: missing %s, unexpected %s" % (missing, extra))
    if problems:
        raise GenerationError("the engine's result is not what the core gave it: " + "; ".join(problems))


# --- the run ----------------------------------------------------------------------------------------------------------------------------------------------

def _prefs(inputs: Inputs) -> List[tuple]:
    """The four prefs of the work profile, in the order of the contract. Absolute paths."""
    return [
        (SECURITY_STATE_GENERATE_PREF, True),
        (INTERMEDIATES_PREF, str(Path(inputs.intermediates).resolve())),
        (ONECRL_PREF, str(Path(inputs.onecrl).resolve())),
        (CRLITE_PREF, str(Path(inputs.crlite).resolve())),
    ]


def _write_user_js(profile: Path, inputs: Inputs) -> None:
    # The lines of `launch.write_user_js`, written by hand: that function is the LAUNCH's writer (it declares the cached intermediates and every other pref of a session), and
    # the work profile of a generation holds exactly the four prefs of the contract. Bytes, LF.
    lines = ["user_pref(%s, %s);" % (json.dumps(k), _pref_literal(k, v)) for k, v in _prefs(inputs)]
    (profile / "user.js").write_bytes(("\n".join(lines) + "\n").encode("utf-8"))


def _remove_tree(path: Path) -> None:
    """Removes `path`, retrying: on Windows a directory stays locked a moment after the last process that used it has gone."""
    for attempt in range(REMOVE_ATTEMPTS):
        try:
            shutil.rmtree(path)
            return
        except FileNotFoundError:
            return
        except OSError:
            if attempt == REMOVE_ATTEMPTS - 1:
                shutil.rmtree(path, ignore_errors=True)
                return
            time.sleep(0.1)


def _end_the_tree(proc: "subprocess.Popen[bytes]", token: SessionToken) -> None:
    """After this nothing of the engine's tree is alive: what carries the session's token is ended (`process.reap_session`, as every launch of the core ends its own), the
    engine itself is reaped, and what is still found is an error to say, not a state to leave."""
    reap_session(token)
    if proc.poll() is None:  # no psutil, or the engine was not found by its token: it is ours, so it is ended by its handle
        proc.kill()
    try:
        proc.wait(timeout=TREE_GONE_WAIT_S)
    except subprocess.TimeoutExpired:
        pass
    if not wait_until_gone(token, TREE_GONE_WAIT_S):
        reap_session(token)
        if not wait_until_gone(token, TREE_GONE_WAIT_S):
            left = [getattr(p, "pid", "?") for p in find_processes(token)]
            raise GenerationError("processes of the engine's tree are still alive after it was ended: %s" % (left,))


def _wait_for_exit(proc: "subprocess.Popen[bytes]", timeout_s: float) -> Optional[int]:
    """The engine's exit code, or None when it has not exited within `timeout_s` seconds. The one place the core waits for the engine: a test replaces it to reach the timeout path
    deterministically, with no clock involved."""
    try:
        return proc.wait(timeout=timeout_s)
    except subprocess.TimeoutExpired:
        return None


def _engine_said(code: int, profile: Path) -> str:
    """The message of a non-zero exit: the code and what the engine's result file says (the engine writes nothing on stdout or stderr, and the core reads none of it)."""
    path = profile / SECURITY_STATE_RESULT_NAME
    try:
        result = json.loads(path.read_bytes().decode("utf-8"))
    except (OSError, ValueError):
        return "the engine exited with %s and left no %s, so the work profile was not writable" % (code, SECURITY_STATE_RESULT_NAME)
    error = result.get("error") if isinstance(result, dict) else None
    return "the engine exited with %s: %s" % (code, error if error else "its %s gives no error" % (SECURITY_STATE_RESULT_NAME,))


def default_argv(binary: "str | os.PathLike[str]") -> List[str]:
    """The launch line of the invisible engine, without the profile: `[binary, "-headless", "-no-remote"]`."""
    return [str(binary), "-headless", "-no-remote"]


def _run(argv: Sequence[str], work: Path, profile: Path, timeout_s: float) -> None:
    """Runs the engine's launch line `argv` (without the profile) plus `-profile <profile>` (a directory of `work`); returns when it exited 0 and its tree is gone, raises `GenerationError` otherwise (its tree gone as well)."""
    token = SessionToken.mint()
    # The environment the core gives every engine it starts (`_engine_env.compose`): the host's `MOZ_*`, GL and toolkit families, zone and language out (`without_the_hosts`),
    # `MOZ_CRASHREPORTER_DISABLE=1` (a crash must not open a dialog nobody reads) and the display backend written on every launch. No locale is declared: a generation shows no
    # page. Then the per-user directories, inside `work` on every platform, so that nothing is written outside it. Stamped with the token, which the engine's children inherit.
    env = _engine_env.compose(dict(os.environ))
    for variable, name in HOME_DIRECTORIES:
        directory = work / name
        directory.mkdir(exist_ok=True)
        env[variable] = str(directory)
    env = token.stamp(env)
    argv = list(argv) + ["-profile", str(profile)]
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if sys.platform == "win32" else 0
    failure: Optional[str] = None
    proc: Optional["subprocess.Popen[bytes]"] = None
    try:
        try:
            proc = subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, env=env, creationflags=flags)
        except OSError as e:
            raise GenerationError("cannot start the engine %r: %s" % (argv[0], e)) from e
        code = _wait_for_exit(proc, timeout_s)
        if code is None:
            failure = "the engine did not finish within %s s; its tree was ended" % (timeout_s,)
        elif code != 0:
            failure = _engine_said(code, profile)
    finally:
        if proc is not None:
            _end_the_tree(proc, token)
    if failure is not None:
        raise GenerationError(failure)


def _check_directory(state: Path) -> None:
    if not state.is_dir():
        raise GenerationError("the engine left no %s directory" % (SECURITY_STATE_DIR_NAME,))
    missing = [n for n in REQUIRED_FILES if not (state / n).is_file() or (state / n).stat().st_size == 0]
    if missing:
        raise GenerationError("the engine's %s directory lacks (or has empty) %s" % (SECURITY_STATE_DIR_NAME, ", ".join(missing)))


def _read_result(path: Path) -> dict:
    try:
        raw = path.read_bytes()
    except OSError as e:
        raise GenerationError("the engine left no %s: %s" % (SECURITY_STATE_RESULT_NAME, e)) from e
    try:
        result = json.loads(raw.decode("utf-8"))
    except ValueError as e:
        raise GenerationError("the engine's %s is not JSON: %s" % (SECURITY_STATE_RESULT_NAME, e)) from e
    if not isinstance(result, dict):
        raise GenerationError("the engine's %s is not a JSON object" % (SECURITY_STATE_RESULT_NAME,))
    return result


def _copy_out(work: Path, out_dir: Path) -> None:
    """Copies the generation into `out_dir` (made here when it did not exist). A copy that fails leaves `out_dir` as it was found."""
    existed = out_dir.exists()
    try:
        out_dir.mkdir(parents=True, exist_ok=True)
        shutil.copytree(work / SECURITY_STATE_DIR_NAME, out_dir / SECURITY_STATE_DIR_NAME, copy_function=shutil.copyfile)
        shutil.copyfile(work / SECURITY_STATE_RESULT_NAME, out_dir / SECURITY_STATE_RESULT_NAME)
    except BaseException:
        if existed:
            for child in out_dir.iterdir():
                if child.is_dir():
                    shutil.rmtree(child, ignore_errors=True)
                else:
                    child.unlink()
        else:
            shutil.rmtree(out_dir, ignore_errors=True)
        raise


def generate(argv: Sequence[str], inputs: Inputs, engine: EngineId, out_dir: Path, *, timeout_s: float = GENERATE_TIMEOUT_S,
             work_root: Optional[Path] = None) -> dict:
    """Has the engine generate the security state from `inputs`, checks its report and puts the result in `out_dir`; returns the report.

    `argv` is the engine's launch line WITHOUT the profile (`default_argv(binary)`, or the caller's own); the core appends exactly `-profile <work profile>`. `engine` is what the core launched (`engine_id_of`). `out_dir` must not exist or be empty: the generation is copied into it
    whole, and only after every check has passed (the caller renames it into the cache). Whatever happens, no process of the engine's tree is alive afterwards and the work profile
    is deleted. `GenerationError` for every refusal."""
    out_dir = Path(out_dir)
    if out_dir.exists() and (not out_dir.is_dir() or any(out_dir.iterdir())):
        raise GenerationError("the output directory %s exists and is not empty" % (out_dir,))
    inputs.expected()  # unreadable inputs refuse here, before an engine is started
    base = Path(tempfile.mkdtemp(prefix="securitystate-", dir=None if work_root is None else str(work_root)))
    try:
        profile = base / "profile"
        profile.mkdir()
        _write_user_js(profile, inputs)
        _run(argv, base, profile, timeout_s)
        result = _read_result(profile / SECURITY_STATE_RESULT_NAME)
        validate_result(result, inputs, engine)
        _check_directory(profile / SECURITY_STATE_DIR_NAME)
        _copy_out(profile, out_dir)
        return result
    finally:
        _remove_tree(base)


def _is_crlite_file(name: str) -> bool:
    """The files of the CRLite filters in `security_state/`: the full filter (`crlite.filter`) and every delta (`*.delta`). Not case-sensitive."""
    low = name.lower()
    return low == CRLITE_FILTER_FILE_NAME or low.endswith(".delta")


def _without_crlite(_directory: str, names: List[str]) -> List[str]:
    return [n for n in names if _is_crlite_file(n)]


def place_in_profile(ready: Path, profile_dir: Path, *, without_crlite: bool = False) -> bool:
    """Puts a copy of the generated `security_state` in a session's profile; False (nothing touched) when `ready` has none.

    A COPY, never a link: the engine rewrites the filter and the delta files in place, and a link would write into the cache and into every other profile. A `security_state` the
    profile already has is replaced. With `without_crlite` the CRLite filter (`crlite.filter`) and every `*.delta` are not copied (the rest, `data.safe.bin`, is): that is what a
    launch with stale data does (`is_stale`)."""
    src = Path(ready) / SECURITY_STATE_DIR_NAME
    if not src.is_dir():
        return False
    dst = Path(profile_dir) / SECURITY_STATE_DIR_NAME
    if dst.is_symlink() or dst.is_file():
        dst.unlink()
    elif dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(src, dst, copy_function=shutil.copyfile, ignore=_without_crlite if without_crlite else None)
    return True


def _stamp_of(updated_utc: Any) -> Optional[datetime]:
    """The moment `updated_utc` says (UTC, whole seconds), or None when it says none."""
    try:
        stamp = datetime.fromisoformat(str(updated_utc).strip().replace("Z", "+00:00"))
    except ValueError:
        return None
    if stamp.tzinfo is None:
        stamp = stamp.replace(tzinfo=timezone.utc)
    return stamp.replace(microsecond=0)


def _age_s(stamp: datetime, now: datetime) -> int:
    current = now if now.tzinfo is not None else now.replace(tzinfo=timezone.utc)
    return int((current.replace(microsecond=0) - stamp).total_seconds())


def is_stale(updated_utc: Any, now: datetime) -> bool:
    """THE rule, used by the warning, by the generation and by the copy into a profile: cert_storage's, at second granularity (lib.rs:464-483: `now < last_update + 10 days` is
    fresh). The data is STALE when `now - updated_utc >= CRLITE_MAX_AGE_S` (exactly ten days is stale) and when `updated_utc` cannot be read. `now` is given, never read from the clock."""
    stamp = _stamp_of(updated_utc)
    return True if stamp is None else _age_s(stamp, now) >= CRLITE_MAX_AGE_S


def age_warning(updated_utc: Any, now: datetime) -> Optional[str]:
    """The text to print (stderr-ready) when the revocation data is stale (`is_stale`), else None.

    cert_storage treats the CRLite filters as absent `CRLITE_MAX_AGE_S` (ten days) after their last update, so a launch with data that old leaves them out of the profile: it is the
    state a retail Firefox has. Exactly ten days is stale. A date that cannot be read is stale too: nothing says how old the data is. `now` is given, never read from the clock."""
    if not is_stale(updated_utc, now):
        return None
    advice = "run `invisible-playwright fetch` to update it"
    days = CRLITE_MAX_AGE_S // 86400
    stamp = _stamp_of(updated_utc)
    if stamp is None:
        return ("warning: the revocation data says no usable date (updated_utc=%r), so its age is unknown; the CRLite filters are left out of the profile because a retail "
                "Firefox does not use them once they are %d days old or more; %s" % (updated_utc, days, advice))
    return ("warning: the CRLite filters are left out of the profile because the revocation data is %d days old (updated %s); from %d days on a retail Firefox does not use "
            "them; %s" % (_age_s(stamp, now) // 86400, stamp.strftime("%Y-%m-%dT%H:%M:%SZ"), days, advice))
